const { createServer } = require('node:http');
const { createAAPWebSocket } = require('aap-agent-server');

const server = createServer();
const aap = createAAPWebSocket({
  server,
  path: '/aap',
  requireSignature: true,
  onVerified: (result) => console.log('Verified:', result.publicId)
});

server.listen(3000, () => {
  console.log('AAP WebSocket server running on port 3000 at /aap');
});

const { AAPClient, createSolver } = require('aap-agent-client');

async function main() {
  const client = new AAPClient({
    serverUrl: 'ws://localhost:3000/aap'
  });

  const solver = createSolver();

  try {
    const result = await client.verify(solver);
    console.log('Verification result:', result);
  } catch (error) {
    console.error('Verification failed:', error.message);
  }
}

main();

```


